        "legalBundleDigest",
        "legalBundleVersion",
        "legalDocumentDigests",
        "planId",
        "providerCustomerRef",
        "providerInvoiceRef",
        "providerReceiptRef",
        "providerSubscriptionRef",
        "providerTransactionRef",
        "purchaseId",
        "representedCapacity",
        "supersessionProcedure",
        "workspaceId"
