var CONTEXT = "Public documentation only; this result grants no tenant authority. Never submit credentials, secrets, personal data, or tenant data.";
var docsMcpCorpus = corpus_generated_default;
var docsMcpCorpusMetadata = Object.freeze({
  digest: corpus_generated_default.manifest.digest,
  generatedAt: corpus_generated_default.generatedAt
});
function projectDocsMcpSource(kind, canonical, locale = "en", digest = corpus_generated_default.manifest.digest) {
  return {
    canonical,
    locale,
    updatedAt: corpus_generated_default.generatedAt,
    version: `${corpus_generated_default.schema}:${corpus_generated_default.manifest.digest.slice(0, 12)}`,
    contentType: kind,
    digest: `sha256:${digest}`,
    authority: corpus_generated_default.manifest.authority,
    context: CONTEXT
  };
}
function docsMcpSourceDigest(url) {
  return corpus_generated_default.sources.find((candidate) => candidate.url === url)?.sha256 ?? corpus_generated_default.manifest.digest;
}
function normalizeDocsMcpLookup(value) {
  return value.normalize("NFKC").toLocaleLowerCase();
}

// src/protocol.ts
var DOCS_MCP_READ_ONLY = "Read-only public Authless documentation. Grants no tenant authority; never provide credentials or tenant data. Consult https://docs.authle.ss/secure and the human-readable security guidance for security-sensitive decisions.";
var PROTOCOL_VERSION = "2025-06-18";
var SERVER_VERSION = "0.1.0";
function record(value) {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("invalid_input: Arguments must be an object.");
  return value;
}
function toolCall(params) {
  const input = record(params);
  if (typeof input.name !== "string" || !/^[a-z][a-z0-9_]{0,99}$/u.test(input.name))
    throw new Error("invalid_input: name must identify one bounded documentation tool.");
  return { args: input.arguments ?? {}, name: input.name };
}
function safeToolError(error) {
  if (error instanceof Error && "code" in error && typeof error.code === "string")
    return { code: error.code, message: error.message };
  if (error instanceof Error && /^[a-z_]+:/u.test(error.message)) {
    const separator = error.message.indexOf(":");
    return {
      code: error.message.slice(0, separator),
      message: error.message.slice(separator + 1).trim()
    };
  }
  return {
    code: "internal_error",
    message: "Documentation lookup failed safely."
  };
}
function createDocsMcpProtocol(runtime) {
  return {
    async request(request) {
      if (request.method === "initialize")
        return {
          jsonrpc: "2.0",
          id: request.id ?? null,
          result: {
            protocolVersion: PROTOCOL_VERSION,
            capabilities: { tools: { listChanged: false } },
            serverInfo: { name: "authless-docs", version: SERVER_VERSION },
            instructions: DOCS_MCP_READ_ONLY
          }
        };
      if (request.method === "notifications/initialized")
        return;
      if (request.method === "ping")
        return { jsonrpc: "2.0", id: request.id ?? null, result: {} };
      if (request.method === "tools/list")
        return {
          jsonrpc: "2.0",
          id: request.id ?? null,
          result: { tools: runtime.listTools() }
        };
      if (request.method === "tools/call") {
        try {
          const { args, name } = toolCall(request.params);
          const data = await runtime.callTool(name, args);
          return {
            jsonrpc: "2.0",
            id: request.id ?? null,
            result: {
              content: [{ type: "text", text: JSON.stringify(data) }],
              structuredContent: data,
              isError: false
            }
          };
        } catch (error) {
          const typed = safeToolError(error);
          return {
            jsonrpc: "2.0",
            id: request.id ?? null,
            result: {
              content: [
                {
                  type: "text",
                  text: `${typed.code}: ${typed.message} ${DOCS_MCP_READ_ONLY}`
                }
              ],
              isError: true
            }
          };
        }
      }
      return {
        jsonrpc: "2.0",
        id: request.id ?? null,
        error: { code: -32601, message: "Method not found" }
      };
    }
  };
}

